55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final TelephoneNormalizer telephoneNormalizer;
69	
70	    private final HouseholdNormalizer householdNormalizer;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 TelephoneNormalizer telephoneNormalizer,
77	                                 HouseholdNormalizer householdNormalizer) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	        this.telephoneNormalizer = telephoneNormalizer;
83	        this.householdNormalizer = householdNormalizer;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
117	        // A value that cannot form a valid E.164 number is rejected with 400.
118	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
119	        owner.setTelephone(normalizedTelephone);
120	        // Store the (already syntactically validated) email lower-cased so it is persisted and
121	        // returned in canonical form. A missing email is left untouched.
122	        owner.setEmail(normalizeEmail(owner.getEmail()));
123	        // Default the registration date to the server's current date when the client did not
124	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
125	        if (owner.getRegistrationDate() == null) {
126	            owner.setRegistrationDate(java.time.LocalDate.now());
127	        }
128	        // Reject creating an owner whose normalized telephone is already used by another owner.
129	        if (isTelephoneInUse(normalizedTelephone)) {
130	            throw new DuplicateTelephoneException(
131	                "An owner with telephone " + normalizedTelephone + " already exists");
132	        }
133	        // Identify any existing owners who share a household (same last name and address,
134	        // compared case-insensitively with collapsed whitespace) with the owner being created.
135	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        // Reject creating an owner who shares a household with an existing owner, unless the
138	        // request explicitly opts in with 'sharesHousehold' true.
139	        if (!sharesHousehold && !householdMembers.isEmpty()) {
140	            throw new DuplicateHouseholdException(
141	                "An owner with the same last name and address already exists");
142	        }
143	        // When opting in and joining an existing household, assign the new owner and every
144	        // existing member the same stable household identifier derived from the last name and
145	        // address, so all owners of the household share one 'householdId'.
146	        if (sharesHousehold && !householdMembers.isEmpty()) {
147	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
148	            owner.setHouseholdId(householdId);
149	            for (Owner member : householdMembers) {
150	                if (!householdId.equals(member.getHouseholdId())) {
151	                    member.setHouseholdId(householdId);
152	                    this.clinicService.saveOwner(member);
153	                }
154	            }
155	        }
156	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
157	        // equal to one more than the current number of owners, fixed at creation time.
158	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
159	        this.clinicService.saveOwner(owner);
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        headers.setLocation(UriComponentsBuilder.newInstance()
162	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
163	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    /**
167	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
168	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
169	     * syntactically valid address (rejecting anything else with 400).
170	     *
171	     * @param email the email value (may be {@code null})
172	     * @return the lower-cased email, or {@code null} if the input was {@code null}
173	     */
174	    private String normalizeEmail(String email) {
175	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
176	    }
177	
178	    /**
179	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
180	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
181	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
182	     *
183	     * @param lastName the owner's last name
184	     * @return the formatted customer code
185	     */
186	    private String nextCustomerCode(String lastName) {
187	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
188	            .toUpperCase(java.util.Locale.ROOT);
189	        int sequence = this.clinicService.findAllOwners().size() + 1;
190	        return String.format("%s-%04d", prefix, sequence);
191	    }
192	
193	    /**
194	     * Determines whether the given normalized telephone is already used by an existing owner.
195	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
196	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
197	     * as the same number.
198	     *
199	     * @param normalizedTelephone the normalized (E.164) telephone to look for
200	     * @return {@code true} if another owner already uses this telephone
201	     */
202	    private boolean isTelephoneInUse(String normalizedTelephone) {
203	        if (normalizedTelephone == null) {
204	            return false;
205	        }
206	        return this.clinicService.findAllOwners().stream()
207	            .map(Owner::getTelephone)
208	            .map(telephoneNormalizer::normalize)
209	            .anyMatch(normalizedTelephone::equals);
210	    }
211	
212	    /**
213	     * Returns the existing owners who share the given household, i.e. have the same last name and
214	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
215	     * differing only in letter case or in incidental whitespace are treated as the same household.
216	     *
217	     * @param lastName the last name of the owner being created
218	     * @param address  the address of the owner being created
219	     * @return the existing owners with a matching last name and address (possibly empty)
220	     */
221	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
222	        String householdKey = householdNormalizer.householdKey(lastName, address);
223	        return this.clinicService.findAllOwners().stream()
224	            .filter(existing -> householdNormalizer
225	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
226	            .toList();
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        // Normalize the telephone to canonical E.164 form so it is stored and returned
241	        // consistently with create; an unformattable value is rejected with 400.
242	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
243	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
244	        this.clinicService.saveOwner(currentOwner);
245	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Transactional
250	    @Override
251	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        this.clinicService.deleteOwner(owner);
257	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
263	        Owner owner = this.clinicService.findOwnerById(ownerId);
264	        if (owner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        HttpHeaders headers = new HttpHeaders();
268	        Pet pet = petMapper.toPet(petFieldsDto);
269	        owner.setId(ownerId);
270	        pet.setOwner(owner);
271	        pet.getType().setName(null);
272	        this.clinicService.savePet(pet);
273	        PetDto petDto = petMapper.toPetDto(pet);
274	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
275	            .buildAndExpand(pet.getId()).toUri());
276	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner != null) {
284	            Pet currentPet = this.clinicService.findPetById(petId);
285	            if (currentPet != null) {
286	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
287	                currentPet.setName(petFieldsDto.getName());
288	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
289	                this.clinicService.savePet(currentPet);
290	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
291	            }
292	        }
293	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
299	        HttpHeaders headers = new HttpHeaders();
300	        Visit visit = visitMapper.toVisit(visitFieldsDto);
301	        Pet pet = new Pet();
302	        pet.setId(petId);
303	        visit.setPet(pet);
304	        this.clinicService.saveVisit(visit);
305	        VisitDto visitDto = visitMapper.toVisitDto(visit);
306	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
307	            .buildAndExpand(visit.getId()).toUri());
308	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
309	    }
310	
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
315	        Owner owner = this.clinicService.findOwnerById(ownerId);
316	        if (owner != null) {
317	            Pet pet = owner.getPet(petId);
318	            if (pet != null) {
319	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	}
